// PRIMARY: consensus/types/src/execution_requests.rs:ExecutionRequests::requests_hash (lines 70-82)
/// Generate the execution layer `requests_hash` based on EIP-7685.
/// `sha256(sha256(requests_0) ++ sha256(requests_1) ++ ...)`
pub fn requests_hash(&self) -> Hash256 {
    let mut hasher = DynamicContext::new();
    for request in self.get_execution_requests_list().iter() {
        let mut request_hasher = DynamicContext::new();
        request_hasher.update(request);
        let request_hash = request_hasher.finalize();  // SHA-256 each request individually
        hasher.update(&request_hash);                   // feed digest into outer hasher
    }
    hasher.finalize().into()
}

// PRIMARY: consensus/types/src/execution_requests.rs:ExecutionRequests::requests_hash (lines 70-82)
// Order-dependence: outer hasher.update() is called in iteration order (deposits, withdrawals, consolidations)
